/* Nombres à virgule (Corban, v130) : le point du clavier de l'iPhone devient une virgule dans les cases chiffrées. */
document.addEventListener('input', (e) => {
  const t = e.target;
  if (!t || t.tagName !== 'INPUT' || t.inputMode !== 'decimal' || !t.value.includes('.')) return;
  const p = t.selectionStart;
  t.value = t.value.replace(/\./g, ',');
  try { t.setSelectionRange(p, p); } catch (er) {}
}, true);

/* Textes d'introduction en popup (Corban, v150) : les paragraphes d'aide en tête d'écran (mode de saisie,
   enregistrement automatique…) ne prennent plus de place ; ils s'affichent dans le popup noir en bas,
   puis disparaissent, et reviennent quand on rouvre l'écran. */
(function introToast() {
  const view = $('#view');
  if (!view) return;
  let lastKey = '';
  // 2026-11-04 (Corban) : plus aucune explication automatique à l'ouverture d'un écran ; le texte reste
  // disponible derrière la pastille « i » placée à côté du titre (helpToPopup).
  const say = (els) => { els.forEach((p) => p.classList.add('help-lead')); };
  const scan = () => {
    const h = view.querySelector(':scope > h1');
    const key = currentView + '|' + (h ? h.textContent : '');
    const lead = [];
    for (let el = view.firstElementChild; el; el = el.nextElementSibling) {
      if (el.matches('h1, .nav-dup, .prep-title')) continue;
      if (el.matches('p.help')) { lead.push(el); continue; }
      break;
    }
    if (!lead.length) { lastKey = key; return; }
    if (key !== lastKey) say(lead);
    lastKey = key;
  };
  new MutationObserver(() => requestAnimationFrame(scan)).observe(view, { childList: true });
  // Mes bateaux : l'aide en tête d'un bateau ouvert passe aussi dans le popup.
  view.addEventListener('toggle', (e) => {
    const d = e.target;
    if (!d.open || !d.matches || !d.matches('details[data-b]')) return;
    const p = d.querySelector(':scope > p.help');
    if (p) say([p]);
  }, true);
})();
// v172 : dans l'aperçu (cadre), les liens d'appel et de courriel s'ouvrent hors du cadre.
